import{renderMansfieldValue,applyScenario,sampleScenario,resetScenario,mansfieldSources}from'./mansfield-value.js';
import{renderFreightNetwork,zoomMap,setMapExtent,panMap,resetMapCamera}from'./network-map.js';
import{demoAdapter}from'./adapter.js';
import{AS_OF,SYNC,CUSTOMER,facilities,nodes,terminals,carriers,statusNames,owners,exceptionStates,lookup,isActive,localDate,makeData,emptyFilters,filterShipments,openExceptions,metrics,laneGroups,updateException,csv}from'./data.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n),num=n=>new Intl.NumberFormat('en-US').format(n),pct=n=>n===null?'—':n.toFixed(1)+'%';
const stamp=(s,zone='America/Indiana/Indianapolis')=>s?new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short',timeZone:zone}).format(new Date(s)):'Unavailable';
const shortDate=s=>s?new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',timeZone:'America/Indiana/Indianapolis'}).format(new Date(s)):'—';
const age=s=>{const h=Math.max(0,Math.floor((new Date(AS_OF)-new Date(s))/3600000));return h>=24?`${Math.floor(h/24)}d ${h%24}h`:`${h}h`};
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',truck:'M1 5h14v12H1z M15 9h4l4 4v4h-8 M5 17a2 2 0 1 0 .1 0 M18 17a2 2 0 1 0 .1 0',building:'M3 21V8l9-5 9 5v13 M8 21v-7h8v7 M7 10h1 M12 10h1 M17 10h1 M1 21h22',alert:'M12 3 2 21h20L12 3z M12 9v5 M12 17h.01',chart:'M3 3v18h18 M7 17v-5 M12 17V7 M17 17v-8',spark:'M12 2l2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5L12 2z',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',arrow:'M4 12h16 M14 6l6 6-6 6',down:'M6 9l6 6 6-6',close:'M6 6l12 12 M6 18 18 6',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',calendar:'M4 5h16v16H4z M8 2v6 M16 2v6 M4 10h16',bell:'M18 8a6 6 0 0 0-12 0v7l-2 3h16l-2-3V8 M10 21h4',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 6v6l4 2',check:'M5 12l4 4L20 5',dollar:'M12 2v20 M17 5H9a4 4 0 0 0 0 8h6a3 3 0 0 1 0 6H6',box:'m3 7 9-5 9 5v10l-9 5-9-5V7z M3 7l9 5 9-5 M12 12v10',filter:'M3 4h18l-7 8v7l-4 2v-9L3 4z',refresh:'M20 7a9 9 0 1 0 1 9 M20 2v6h-6',info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 11v6 M12 7h.01',list:'M8 5h13 M8 12h13 M8 19h13 M3 5h.01 M3 12h.01 M3 19h.01',map:'m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3V6z M9 3v15 M15 6v15',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M3 21v-2a9 9 0 0 1 18 0v2',file:'M14 2H5v20h14V7l-5-5z M14 2v6h5 M8 12h8 M8 16h8',chevron:'M9 5l7 7-7 7',layers:'m12 3 10 6-10 6L2 9l10-6z M2 14l10 6 10-6',back:'M20 12H4 M10 6l-6 6 6 6',shield:'M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4z M8 11l3 3 5-5'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.box}"/></svg>`;
const btn=(label,action,id='',cls='')=>`<button type="button" class="btn ${cls}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
const link=(label,action,id='')=>`<button type="button" class="link" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
const pill=(label,color='')=>`<span class="pill ${color}">${esc(label)}</span>`;
const status=s=>pill(s.status,s.status==='Delivered'?'teal':['Unknown','Partially delivered'].includes(s.status)?'amber':s.status==='Cancelled'?'':'blue');
const severity=e=>pill(e.severity,e.severity==='High'?'red':e.severity==='Medium'?'amber':'blue');
const route=s=>`<div class="route"><b>${s.origin}</b>${icon('arrow')}<b>${s.destination}</b></div>`;
const STORAGE='bhd-ltl-mansfield-v2';let storageProblem=false;
let data;try{const d=JSON.parse(localStorage.getItem(STORAGE));data=d?.version===2?d:demoAdapter.createInitialSnapshot()}catch{data=demoAdapter.createInitialSnapshot();storageProblem=true}
let view='Overview',filters=emptyFilters(),role='corporate',facilityPage=null,mapMode='locations',mapList=window.matchMedia('(max-width:600px)').matches,mapWeight='volume',sortKey='id',sortAsc=false,page=1,columns={references:false,weight:false,charges:true},exceptionTab='Open',drawer=null,drawerTab='Overview',focusReturn=null;
const finance=()=>role!=='facility',internal=()=>['operations','admin'].includes(role),editable=()=>['operations','admin','corporate','facility'].includes(role);
const allPermitted=()=>filterShipments(data,emptyFilters(),role);
const ships=()=>filterShipments(data,filters,role);
const save=()=>{try{localStorage.setItem(STORAGE,JSON.stringify(data))}catch{storageProblem=true;toast('Browser storage unavailable. Changes will last only for this session.')}};
const toast=t=>{$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500)};
const options=(items,value,all)=>`${all?`<option value="all">${all}</option>`:''}`+items.map(x=>{const [v,l]=Array.isArray(x)?x:[x,x];return`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`}).join('');
const select=(name,items,all)=>`<select aria-label="${name==='date'?'Reporting period':name==='freightClass'?'Freight class':name}" data-filter="${name}">${options(items,filters[name],all)}</select>`;
function header(){return`<header class="site-header"><div class="header-inner"><div class="brand"><img src="bhd-logo.svg" alt="Backhaul Direct"><span class="brand-divider"></span><span class="brand-title">LTL CONTROL<br>CENTER</span></div><nav class="mainnav" aria-label="Main navigation">${['Overview','Shipments','Facilities','Exceptions','Insights','Opportunities','Mansfield'].map(n=>`<button data-action="nav" data-id="${n}" class="${view===n?'active':''}" ${view===n?'aria-current="page"':''}>${n}</button>`).join('')}</nav><div class="header-tools"><button class="icon-btn" aria-label="Open network alerts" data-action="alerts">${icon('bell')}<span class="alert-count">${openExceptions(data,allPermitted()).length}</span></button><button class="avatar" aria-label="Demo user menu and roles" data-action="user">${internal()?'BH':'AM'}</button></div></div></header><div class="context-bar"><div class="customer"><span class="customer-mark">M</span>${CUSTOMER.name}<span class="muted">/</span><span class="muted">${role==='facility'?'Gainesville workspace':'Corporate network'}</span><span class="demo-badge">DEMO FREIGHT</span></div><div class="freshness"><span class="dot"></span><span>Demo snapshot · Oct 30, 2026, noon EDT</span><span class="long">&nbsp; | &nbsp; Sync 11:45 AM EDT</span></div></div>`}
function top(){const titles={Mansfield:['Built around Mansfield’s priorities','Protect supply continuity, tighten financial control, and validate the receiving network.'],Overview:['Network overview','Your facilities. Your freight. One network.'],Shipments:['Every shipment. One clear view.','Follow freight across your network, from pickup through final delivery.'],Facilities:['Your facility network','11 published locations. Real directory details with clearly marked demo freight.'],Exceptions:['Keep freight moving','A shared workspace for issues, owners, and the next action.'],Insights:['See what drives your network','Customer spend and service performance, with the numbers behind every measure.'],Opportunities:['A smarter way to move freight','Turn recurring network patterns into opportunities for BHD review.']};let[t,d]=titles[view];if(facilityPage){t=lookup(facilityPage).name+' workspace';d=facilities.find(f=>f.id===facilityPage).type+' · Arrivals, departures, and local priorities.'}return`<div class="page-head"><div><div class="eyebrow">${facilityPage?'FACILITY OPERATIONS':'MANSFIELD ENERGY CORP'}</div><h1>${t}</h1><p>${d}</p></div><div class="head-tools">${select('date',[['month','Oct 1 – 30, 2026'],['week','Oct 24 – 30, 2026'],['today','Today · Oct 30, 2026']])}${btn(icon('download')+' Export shipments','export')}${btn(icon('info')+' Demo guide','guide','','primary')}</div></div>`}
function filterBar(){return`<div class="filters"><label class="filter-label">${icon('building')}${select('facility',(role==='facility'?facilities.filter(f=>f.id==='GNV'):facilities).map(f=>[f.id,f.name+', '+f.state]),role==='facility'?null:'All facilities')}</label>${select('direction',[['inbound','Inbound'],['outbound','Outbound'],['interfacility','Interfacility']],'All movements')}${select('carrier',carriers,'All carriers')}${select('status',statusNames,'All statuses')}<div class="search">${icon('search')}<input id="global-search" class="input" aria-label="Search shipments by load, PRO, BOL, PO, or city" placeholder="Search load, PRO, BOL or PO…" value="${esc(filters.q)}" autocomplete="off"></div><button class="btn sm" type="button" data-action="reset-filters" aria-label="Reset filters">${icon('refresh')}</button></div>${activeChips()}`}
function activeChips(){return`<div class="chips">${Object.entries(filters).filter(([k,v])=>v&&v!=='all'&&!(k==='date'&&v==='month')&&!(role==='facility'&&k==='facility')).map(([k,v])=>`<span class="chip">${esc(k)}: ${esc(k==='facility'?lookup(v)?.name:v.replace('|',' → '))}<button data-action="clear-filter" data-id="${k}" aria-label="Clear ${k} filter">×</button></span>`).join('')}</div>`}
function kpis(list=ships()){const m=metrics(list,data);return`<div class="kpis">${[
['Active shipments',m.active,'Across the selected network','active','truck',''],['Pickups due today',m.pickups,'Original pickup commitment','pickups','box',''],['Deliveries due today',m.deliveries,'Original delivery commitment','deliveries','building',''],['Open exceptions',m.exceptions,'Assigned and awaiting action','exceptions','alert',m.exceptions?'red':''],['On-time delivery',pct(m.otd),`${m.onTime} of ${m.denominator} delivered loads`,'service','check','teal'],['Freight spend',finance()?money(m.spend):'Restricted',finance()?`${money(m.invoiced)} invoiced · ${money(m.estimated)} est.`:'Finance access required','spend','dollar','']
].map(([label,value,sub,id,ico,cls])=>`<button class="kpi" data-action="metric" data-id="${id}"><span class="kpi-top">${label}${icon(ico)}</span><strong class="${cls}">${value}</strong><small>${sub}</small></button>`).join('')}</div>`}
function table(list,{compact=false}={}){let sorted=[...list].sort((a,b)=>{const x=sortKey==='charge'?(a.charges.invoiced??a.charges.expected):a[sortKey],y=sortKey==='charge'?(b.charges.invoiced??b.charges.expected):b[sortKey];return(typeof x==='number'?x-y:String(x).localeCompare(String(y)))*(sortAsc?1:-1)});const total=sorted.length;if(compact)sorted=sorted.slice(0,5);else{page=Math.max(1,Math.min(page,Math.ceil(total/15)||1));sorted=sorted.slice((page-1)*15,page*15)}
const th=(name,key)=>`<th>${key?`<button data-action="sort" data-id="${key}">${name}${sortKey===key?(sortAsc?' ↑':' ↓'):''}</button>`:name}</th>`;
return`<div class="table-wrap"><table><thead><tr>${th('Shipment','id')}${th('Route')}${th('Carrier','carrier')}${th('Status','status')}${th('Promised delivery','deliveryCommitment')}${th('Last source update','sourceUpdatedAt')}${!compact&&columns.references?th('Order references'):''}${!compact&&columns.weight?th('Freight'):''}${!compact&&columns.charges&&finance()?th('Customer charge','charge'):''}<th><span class="sr-only">Details</span></th></tr></thead><tbody>${sorted.map(s=>`<tr><td>${link(s.id,'shipment',s.id)}<small>${esc(s.pros.map(p=>p.number).join(' / '))}</small></td><td>${route(s)}<small>${lookup(s.origin).name} → ${lookup(s.destination).name}</small></td><td>${esc(s.carrier)}</td><td>${status(s)}${openExceptions(data,[s]).length?'<small class="text-red">Open exception</small>':''}</td><td>${shortDate(s.deliveryCommitment)}<small>${stamp(s.deliveryCommitment).split(', ').slice(1).join(', ')}</small></td><td>${age(s.sourceUpdatedAt)} ago${isActive(s)&&new Date(AS_OF)-new Date(s.sourceUpdatedAt)>86400000?'<small class="text-red">Stale source event</small>':'<small>'+shortDate(s.sourceUpdatedAt)+'</small>'}</td>${!compact&&columns.references?`<td>${s.po}<small>${s.bol}</small></td>`:''}${!compact&&columns.weight?`<td>${s.pallets} pallets<small>${num(s.weight)} lb · Class ${s.class}</small></td>`:''}${!compact&&columns.charges&&finance()?`<td>${money(s.charges.invoiced??s.charges.expected)}<small>${s.charges.invoiced===null?'Estimated':'Invoiced'}</small></td>`:''}<td><button class="icon-btn" data-action="shipment" data-id="${s.id}" aria-label="Open ${s.id}">${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>${!total?empty():''}${compact?`<div class="table-footer"><span>Most recent load IDs in this selection</span>${link('View all shipments '+icon('arrow'),'nav','Shipments')}</div>`:`<div class="table-footer"><span>${total?((page-1)*15+1)+'–'+Math.min(page*15,total):'0'} of ${total} unique loads · Split PROs counted once</span><div class="row"><button class="btn sm" data-action="prev" ${page===1?'disabled':''}>Previous</button><span>Page ${page}</span><button class="btn sm" data-action="next" ${page*15>=total?'disabled':''}>Next</button></div></div>`}`}
const empty=()=>`<div class="empty">${icon('search')}<h3>No matching shipments</h3><p>Try a different facility, date range, or search.</p>${btn('Reset filters','reset-filters','','primary')}</div>`;
function network(){return renderFreightNetwork({shipments:ships(),data,filters,mode:mapMode,list:mapList,weight:mapWeight,finance:finance(),icon})}
function attention(list=ships()){const ex=openExceptions(data,list).sort((a,b)=>({High:0,Medium:1,Low:2}[a.severity]-{High:0,Medium:1,Low:2}[b.severity]));return`<section class="card"><div class="card-head"><h2 class="row">${icon('alert')} Needs attention</h2>${pill(ex.length+' open',ex.length?'amber':'teal')}</div><div class="attention">${ex.slice(0,3).map(e=>`<button class="attention-item" data-action="exception" data-id="${e.id}"><div class="between">${severity(e)}<small>${age(e.detectedAt)} open</small></div><h3>${esc(e.type)} <span class="muted">· ${e.loadId}</span></h3><p>${lookup(e.facility).name} · ${esc(e.nextAction)}</p><span class="owner">${icon('user')}${e.owner}</span></button>`).join('')||'<div class="empty"><h3>All clear for this selection</h3><p>No open exceptions.</p></div>'}</div><div class="attention-bottom"><span>One issue. One accountable owner.</span>${link('View queue '+icon('arrow'),'nav','Exceptions')}</div></section>`}
function facilityCard(f){const list=ships().filter(s=>s.origin===f.id||s.destination===f.id),m=metrics(list,data),inb=list.filter(s=>s.destination===f.id&&isActive(s)).length,out=list.filter(s=>s.origin===f.id&&isActive(s)).length;return`<article class="card facility-card ${filters.facility===f.id?'selected':''}"><div class="facility-top"><span class="facility-icon">${icon('building')}</span><div><h3>${f.name}, ${f.state}</h3><p>${f.type} · ${new Intl.DateTimeFormat('en-US',{timeZone:f.zone,timeZoneName:'short'}).formatToParts(new Date(AS_OF)).find(p=>p.type==='timeZoneName').value}</p></div>${m.exceptions?pill(m.exceptions+' issues','amber'):pill('On track','teal')}</div><div class="facility-numbers"><div><small>Active inbound</small><strong>${inb}</strong></div><div><small>Active outbound</small><strong>${out}</strong></div></div><div class="between small"><span class="muted">On-time delivery</span><strong>${pct(m.otd)}</strong></div><div class="service-track"><span style="width:${m.otd??0}%"></span></div><div class="facility-bottom"><span>${m.onTime}/${m.denominator} delivered on time</span><b>${finance()?money(m.spend):'Finance restricted'}</b></div><div class="facility-source-line">${esc(f.address)}</div>${link('Open facility '+icon('arrow'),'facility',f.id)}</article>`}
function overview(){return`<div class="map-source-banner"><span><strong>11 published Mansfield locations.</strong> Shipment activity and financials are synthetic.</span>${link('Mansfield value tools '+icon('arrow'),'nav','Mansfield')}</div>${kpis()}<div class="network-grid">${network()}${attention()}</div><div class="section-head"><div><h2>Facility pulse</h2><p>Service and activity across your selected network</p></div>${link('View all facilities '+icon('arrow'),'nav','Facilities')}</div><div class="facility-grid">${(role==='facility'?facilities.filter(f=>f.id==='GNV'):filters.facility!=='all'?facilities.filter(f=>f.id===filters.facility):facilities.slice(0,4)).map(facilityCard).join('')}</div><div class="section-head"><h2>Recent shipments</h2><span class="period-label">Fixed demo snapshot · Oct 30, 2026</span></div><section class="card">${table(ships(),{compact:true})}</section>`}
function shipmentPage(){return`<section class="card"><div class="toolbar"><div class="view-tabs">${[['','All shipments'],['active','Active freight'],['exceptions','With exceptions'],['service','Delivered sample']].map(([id,label])=>`<button class="${filters.metric===id?'active':''}" data-action="saved-preset" data-id="${id}">${label}</button>`).join('')}</div><div class="row">${data.savedViews.length?`<select id="saved-view" aria-label="Saved shipment views"><option value="">Saved views</option>${data.savedViews.map((v,i)=>`<option value="${i}">${esc(v.name)}</option>`).join('')}</select>`:''}${btn('Save view','save-view','','sm')}${btn(icon('layers')+' Columns','columns','','sm')}</div></div>${table(ships())}</section><p class="small muted" style="margin-top:12px">Reporting basis: original pickup date, in Indianapolis time. Original commitments remain separate from revised ETAs. ${link('Metric definitions','definitions')}</p>`}
function facilitiesPage(){if(facilityPage)return facilityDetail();return`<div class="note page-note">Compare like-for-like freight. Shipment mix, distance, class, accessorials, and service requirements affect cost. ${link('Read metric definitions','definitions')}</div><div class="filters">${select('weight',[['light','Under 3,000 lb'],['heavy','3,000 lb and above']],'All weight bands')}${select('freightClass',['70','85','100','125'],'All freight classes')}<span class="small muted">Service: Standard LTL · Use lane selections for matched-lane comparisons.</span></div><div class="facility-grid">${(role==='facility'?facilities.filter(f=>f.id==='GNV'):facilities).map(facilityCard).join('')}</div><div class="section-head"><h2>Today's facility schedule</h2><span class="small muted">In each facility's local time</span></div><div class="card table-wrap"><table><thead><tr><th>Facility</th><th>Pickups today</th><th>Deliveries today</th><th>Open issues</th><th>Receiving hours</th></tr></thead><tbody>${(role==='facility'?facilities.filter(f=>f.id==='GNV'):facilities).map(f=>{const list=ships().filter(s=>s.status!=='Cancelled'),pick=list.filter(s=>s.origin===f.id&&localDate(s.pickupCommitment,f.zone)==='2026-10-30').length,del=list.filter(s=>s.destination===f.id&&localDate(s.deliveryCommitment,f.zone)==='2026-10-30').length;return`<tr><td>${link(f.name,'facility',f.id)}</td><td>${pick}</td><td>${del}</td><td>${openExceptions(data,list.filter(s=>s.origin===f.id||s.destination===f.id)).length}</td><td>${f.hours}</td></tr>`}).join('')}</tbody></table></div>`}
function facilityDetail(){const f=facilities.find(f=>f.id===facilityPage),list=ships(),lanes=laneGroups(list).sort((a,b)=>b.ships.length-a.ships.length).slice(0,5);return`${btn(icon('back')+' All facilities','facility-back','','sm')}<div style="margin-top:14px">${kpis(list)}</div><div class="two-col"><section class="card"><div class="card-head"><h2>Arrivals & departures</h2><div class="row">${btn('Inbound','facility-direction','inbound','sm')}${btn('Outbound','facility-direction','outbound','sm')}</div></div>${table(list,{compact:true})}</section>${attention(list)}</div><div class="two-col"><section class="card pad"><h2>Major lanes</h2><div class="bar-chart">${lanes.map(l=>`<div class="between">${link(lookup(l.origin).name+' → '+lookup(l.destination).name,'lane',l.key)}<small>${l.ships.length} loads · ${finance()?money(l.spend):''}</small></div>`).join('')}</div></section><section class="card pad"><h2>Published location details</h2><dl class="fact-grid"><div><dt>Published phone</dt><dd>${f.phone}</dd></div><div><dt>Receiving hours</dt><dd>${f.hours}</dd></div><div><dt>Time zone</dt><dd>${f.zone}</dd></div><div><dt>Facility ID</dt><dd>${f.id} · ${CUSTOMER.id}</dd></div></dl><div class="note"><strong>${esc(f.address)}</strong><br>${esc(f.quality)} · ${esc(f.sourceNote)}<br><a href="${f.source}" target="_blank" rel="noopener">Mansfield public directory</a> · Reviewed ${f.verifiedOn}<br>Receiving hours, docks, and operational status are not verified.</div></section></div><div class="section-head"><h2>Carrier performance at ${f.name}</h2></div>${carrierTable(list)}`}
function exceptionsPage(){const allowed=new Set(ships().map(s=>s.id)),all=data.exceptions.filter(e=>allowed.has(e.loadId)),list=all.filter(e=>exceptionTab==='All'||(exceptionTab==='Resolved'?e.status==='Resolved':e.status!=='Resolved'));return`<section class="card"><div class="toolbar"><div class="view-tabs">${['Open','Resolved','All'].map(t=>`<button class="${exceptionTab===t?'active':''}" data-action="exception-tab" data-id="${t}">${t} (${all.filter(e=>t==='All'||(t==='Resolved'?e.status==='Resolved':e.status!=='Resolved')).length})</button>`).join('')}</div><span class="small muted">Local demo collaboration</span></div><div class="table-wrap"><table><thead><tr><th>Issue / shipment</th><th>Severity</th><th>Facility</th><th>Owner</th><th>Next action</th><th>Status / age</th><th></th></tr></thead><tbody>${list.map(e=>`<tr><td>${link(e.type,'exception',e.id)}<small>${e.loadId} · ${e.id}</small></td><td>${severity(e)}</td><td>${lookup(e.facility).name}</td><td>${e.owner}</td><td style="max-width:270px;white-space:normal">${esc(e.nextAction)}<small>Due ${stamp(e.dueAt)}</small></td><td>${pill(e.status,e.status==='Resolved'?'teal':'blue')}<small>${age(e.detectedAt)} since detection</small></td><td>${btn('Manage','exception',e.id,'sm')}</td></tr>`).join('')}</tbody></table></div>${!list.length?'<div class="empty"><h3>No '+exceptionTab.toLowerCase()+' exceptions in this selection</h3></div>':''}</section><div class="note" style="margin-top:16px">Assignment, notes, escalation, and resolution are saved in this browser only. A resolved exception never changes the carrier's shipment status.</div>`}
function carrierTable(list){return`<section class="card table-wrap"><table><thead><tr><th>Carrier</th><th>Loads</th><th>On-time delivery</th><th>On-time pickup</th><th>Open exceptions</th>${finance()?'<th>Customer spend</th>':''}</tr></thead><tbody>${carriers.map(c=>{const ss=list.filter(s=>s.carrier===c),m=metrics(ss,data),p=ss.filter(s=>s.status!=='Cancelled'&&s.pickupActual),op=p.filter(s=>s.pickupActual<=s.pickupCommitment).length;return`<tr><td>${link(c,'carrier',c)}</td><td>${ss.length}</td><td><strong>${pct(m.otd)}</strong><small>${m.onTime} of ${m.denominator} completed loads</small></td><td>${p.length?pct(100*op/p.length):'—'}<small>${op} of ${p.length} observed pickups</small></td><td>${m.exceptions}</td>${finance()?`<td>${money(m.spend)}<small>Invoiced + estimated</small></td>`:''}</tr>`}).join('')}</tbody></table></section>`}
function insights(){const list=ships(),m=metrics(list,data),valid=list.filter(s=>s.status!=='Cancelled'),weight=valid.reduce((a,s)=>a+s.weight,0);const dimension=insightDimension;let groups;if(dimension==='facility'){groups=facilities.map(f=>({key:f.id,label:f.name,list:valid.filter(s=>s.origin===f.id||( !facilities.some(x=>x.id===s.origin)&&s.destination===f.id))}));}else if(dimension==='carrier'){groups=carriers.map(c=>({key:c,label:c,list:valid.filter(s=>s.carrier===c)}))}else{groups=laneGroups(valid).map(l=>({key:l.key,label:l.origin+' → '+l.destination,list:l.ships}))}groups=groups.map(g=>({...g,m:metrics(g.list,data)})).filter(g=>g.list.length).sort((a,b)=>b.m.spend-a.m.spend);const max=Math.max(1,...groups.map(g=>g.m.spend)),weeks=[[1,7],[8,14],[15,21],[22,30]].map(([a,b])=>({label:`Oct ${a}–${b}`,m:metrics(valid.filter(s=>+s.shipDate.slice(-2)>=a&&+s.shipDate.slice(-2)<=b),data)}));const mx=Math.max(1,...weeks.map(w=>w.m.spend));const acc=valid.filter(s=>s.charges.accessorial>0),totalAcc=acc.reduce((a,s)=>a+s.charges.accessorial,0);const resolved=data.exceptions.filter(e=>e.status==='Resolved'&&list.some(s=>s.id===e.loadId));const resolution=resolved.length?resolved.reduce((a,e)=>a+(new Date(e.history.at(-1).time)-new Date(e.detectedAt))/3600000,0)/resolved.length:null;const claims=new Set(data.exceptions.filter(e=>e.type==='Shortage / damage'&&list.some(s=>s.id===e.loadId)).map(e=>e.loadId));return`${kpis(list)}<div class="two-col"><section class="card pad"><div class="between"><h2>Customer spend by ${dimension}</h2><select id="insight-dimension" aria-label="Spend breakdown">${options(['facility','carrier','lane'],dimension)}</select></div>${finance()?`<div class="bar-chart">${groups.map(g=>`<div class="bar-row"><span>${esc(g.label)}</span><div class="bar-bg" title="${money(g.m.invoiced)} invoiced, ${money(g.m.estimated)} estimated"><span class="bar" style="width:${g.m.invoiced/max*100}%"></span><span class="bar estimate" style="width:${g.m.estimated/max*100}%"></span></div><b>${money(g.m.spend)}</b></div>`).join('')}</div><div class="legend"><span><i></i>Invoiced</span><span><i class="lime"></i>Estimated, not invoiced</span></div><p class="small muted" style="margin-top:15px">${dimension==='facility'?'Spend is allocated once: customer origin, or customer destination for inbound supplier loads.':'Amounts include linehaul, fuel, and accessorials once.'}</p>`:'<div class="empty">Finance view is unavailable in this demo role.</div>'}</section><section class="card pad"><h2>Spend over the reporting period</h2>${finance()?`<svg class="chart-svg" viewBox="0 0 440 150" role="img" aria-label="Customer spend by pickup week">${[0,1,2].map(i=>`<line x1="20" y1="${20+i*45}" x2="430" y2="${20+i*45}" stroke="#e8edf2"/>`).join('')}${weeks.map((w,i)=>{let h=w.m.spend/mx*90;return`<rect x="${40+i*105}" y="${115-h}" width="50" height="${h}" fill="#1c3a62" rx="3"/><text x="${65+i*105}" y="${108-h}" text-anchor="middle" fill="#627083" font-size="9">${money(w.m.spend)}</text><text x="${65+i*105}" y="140" text-anchor="middle" fill="#627083" font-size="10">${w.label}</text>`}).join('')}</svg><div class="spend-summary"><div><small>Cost / shipment</small><strong>${m.spendCount?money(m.spend/m.spendCount):'—'}</strong></div><div><small>Cost / hundredweight</small><strong>${weight?money(m.spend/(weight/100)):'—'}</strong></div></div><div class="note" style="margin-top:20px">${m.spendCount} noncancelled loads · ${num(weight)} lb. Includes estimates. Cost differences reflect lane and freight mix; they are not an efficiency ranking.</div>`:'<div class="empty">Finance access required.</div>'}</section></div><div class="section-head"><h2>Carrier service scorecard</h2>${link('How we measure service','definitions')}</div>${carrierTable(list)}<div class="three-col" style="margin-top:18px"><section class="card pad"><h3>Accessorials</h3><p class="stat-big" style="margin-top:10px">${finance()?money(totalAcc):'Restricted'}</p><p class="small muted">${acc.length} of ${valid.length} loads · Liftgate and appointment fees</p><div class="note" style="margin-top:14px">Included in expected customer charges. Invoice-only adjustments are shown separately.</div></section><section class="card pad"><h3>Expected vs. invoiced</h3><p class="stat-big" style="margin-top:10px">${finance()?money(valid.filter(s=>s.charges.invoiced!==null).reduce((a,s)=>a+s.charges.invoiced-s.charges.expected,0)):'Restricted'}</p><p class="small muted">Net variance · ${valid.filter(s=>s.charges.invoiced!==null).length} invoiced loads</p><div class="note" style="margin-top:14px">Compare only loads with both values. Active estimates are excluded from the variance.</div></section><section class="card pad"><h3>Claims & resolution</h3><p class="stat-big" style="margin-top:10px">${valid.length?pct(claims.size/valid.length*100):'—'}</p><p class="small muted">${claims.size} damage/shortage reports / ${valid.length} loads</p><div class="note" style="margin-top:14px">Mean resolution time: ${resolution===null?'No resolved sample':Math.max(0,resolution).toFixed(1)+' hours ('+resolved.length+' resolved)'}. Reports are not confirmed paid claims.</div></section></div>`}
let insightDimension='facility';
const opportunityDefs=[{id:'OP-101',type:'Consolidation candidate',title:'Three loads. One shared lane.',route:'Gainesville → Mark',description:'Three compatible demo shipments share a ready date, destination, and delivery window.',icon:'layers',ids:['SB-260554','SB-260555','SB-260556'],action:'Validate a volume LTL or pooled move with BHD.',assumptions:['All shipment data is synthetic. Mark is a published PO-box location, not a verified receiving dock; validate physical endpoints before any real review.','Three loads · 9 pallets · 6,300 lb.','Ready Oct 30 at noon EDT; delivery by Nov 2 at 5 PM EST.','48 × 40 × 48 in per pallet; stackable, dry, nonhazardous.','Trailer capacity, final handling compatibility, dock time, and current carrier pricing still require validation.'],savings:'Illustrative 10–15% of selected expected charges; no carrier quote or realized savings.'},{id:'OP-102',type:'Preventable accessorials',title:'Get ahead of liftgate charges.',route:'Network-wide',description:'Repeated liftgate fees may point to receiving requirements that can be planned earlier.',icon:'building',dynamic:'accessorial',action:'Review receiving equipment and accessorial authorization by location.',assumptions:['Supporting loads have an $85 liftgate fee in expected customer charges.','Confirm that a dock or forklift is actually available before proposing a change.','Do not remove needed equipment or reduce service to generate a savings claim.'],savings:'Not quantified. Any avoided fee must be verified against actual future invoices.'},{id:'OP-103',type:'Recurring lane review',title:'Build a better repeat lane.',route:'Houston → Gainesville',description:'A recurring lane is a candidate for a scheduled volume program and a service review.',icon:'truck',dynamic:'lane',action:'Review cadence, delivery commitments, freight mix, and carrier options.',assumptions:['Historical repeat patterns are an initial signal only.','Ready-date flexibility, dimensions, stackability, volume continuity, capacity, and current pricing must be confirmed.','A pool or scheduled program must preserve customer service windows.'],savings:'Not quantified. No booking or load changes are made.'}];
const opportunityShips=o=>ships().filter(s=>o.ids?o.ids.includes(s.id):o.dynamic==='accessorial'?s.charges.accessorial===85:s.origin==='HOU'&&s.destination==='GNV');
function opportunities(){return`<div class="note lime page-note">Ideas for review, backed by the selected shipments. Estimated savings are not realized savings. Sending for BHD review creates a local demo review item.</div><div class="three-col">${opportunityDefs.map(o=>{const list=opportunityShips(o),r=data.reviews.find(r=>r.id===o.id);return`<article class="card opportunity"><div class="between"><span class="icon-tile">${icon(o.icon)}</span>${pill(r?'In review':'Candidate',r?'teal':'lime')}</div><div class="eyebrow">${o.type}</div><h3>${o.title}</h3><p>${o.description}</p><div class="note"><strong>${o.route}</strong><br>${list.length} supporting shipments in this selection${finance()?' · '+money(metrics(list,data).spend):''}</div><p class="small">Review owner: ${r?'BHD Operations':'Unassigned'}</p>${btn('Review opportunity '+icon('arrow'),'opportunity',o.id,'primary')}</article>`}).join('')}</div>${data.reviews.length?`<div class="section-head"><h2>Review queue</h2></div><div class="card table-wrap"><table><thead><tr><th>Review</th><th>Owner</th><th>Status</th><th>Created</th></tr></thead><tbody>${data.reviews.map(r=>`<tr><td>${link(r.id+' · '+r.title,'opportunity',r.id)}</td><td>BHD Operations</td><td>${pill('Awaiting BHD review','blue')}</td><td>${stamp(r.createdAt)}</td></tr>`).join('')}</tbody></table></div>`:''}`}
function footer(){return`<footer class="footer"><span>Powered by Backhaul Direct · Sunnybrook remains the load system of record.</span><div class="row">${link('Data & metric definitions','definitions')}${link('Integration readiness','integration')}<a class="link" href="handoff.txt" download="BHD_LTL_Control_Center_Handoff.txt">Developer handoff</a>${link('Reset demo','reset-demo')}</div></footer>`}
function render(){const active=document.activeElement,focus=active?.id==='global-search'?{start:active.selectionStart,end:active.selectionEnd}:null;$('#app').innerHTML=header()+`<main class="content" id="main" tabindex="-1">${top()}${filterBar()}${storageProblem?'<div class="note amber page-note">Browser persistence is unavailable. Demo changes are session-only.</div>':''}${({Overview:overview,Shipments:shipmentPage,Facilities:facilitiesPage,Exceptions:exceptionsPage,Insights:insights,Opportunities:opportunities,Mansfield:()=>renderMansfieldValue({ships:ships(),data,finance:finance(),icon,link,btn})}[view])()}${footer()}</main>`;if(focus){$('#global-search').focus();$('#global-search').setSelectionRange(focus.start,focus.end)}}
function closeOverlay(){const old=drawer;drawer=null;$('#overlay').innerHTML='';document.body.style.overflow='';if(location.hash.startsWith('#load='))history.replaceState(null,'',location.pathname+location.search);if(focusReturn?.isConnected)focusReturn.focus();else if(old)$('#main')?.focus()}
function overlay(html,type='drawer'){focusReturn=document.activeElement;$('#overlay').innerHTML=`<div class="overlay ${type==='modal'?'modal-wrap':''}" data-action="overlay-background"><section class="${type}" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabindex="-1">${html}</section></div>`;document.body.style.overflow='hidden';$('#overlay [data-action="close"]')?.focus()}
const closeBtn=()=>`<button class="icon-btn" aria-label="Close dialog" data-action="close">${icon('close')}</button>`;
function modal(title,body){drawer={kind:'modal'};overlay(`<div class="modal-head"><h2 id="dialog-title">${title}</h2>${closeBtn()}</div><div class="modal-body">${body}</div>`,'modal')}
function openShipment(id,tab=drawerTab){const s=allPermitted().find(s=>s.id===id);if(!s){modal('Shipment unavailable','<p>This shipment is not available in the selected demo role.</p>');return}drawer={kind:'shipment',id};drawerTab=tab;history.replaceState(null,'','#load='+encodeURIComponent(id));const ex=data.exceptions.filter(e=>e.loadId===id),stale=isActive(s)&&new Date(AS_OF)-new Date(s.sourceUpdatedAt)>86400000;let body='';
if(tab==='Overview')body=`<div class="drawer-route"><div><small>ORIGIN</small><strong>${lookup(s.origin).name}, ${lookup(s.origin).state}</strong></div>${icon('arrow')}<div><small>DESTINATION</small><strong>${lookup(s.destination).name}, ${lookup(s.destination).state}</strong></div></div><div class="between" style="margin-bottom:18px">${status(s)}<small>${s.carrier} · Standard LTL</small></div>${s.status==='Partially delivered'?'<div class="note amber page-note">Only one of two PROs has delivered. This load remains active until every piece is confirmed delivered.</div>':''}${stale?'<div class="note red page-note">Stale carrier data · '+age(s.sourceUpdatedAt)+' since the last source update. The later system sync does not make this event fresh.</div>':''}<section class="drawer-section"><h3>Commitments & current estimates</h3><dl class="fact-grid"><div><dt>Original pickup commitment</dt><dd>${stamp(s.pickupCommitment)}</dd></div><div><dt>Actual pickup</dt><dd>${stamp(s.pickupActual)}</dd></div><div><dt>Original delivery commitment</dt><dd>${stamp(s.deliveryCommitment)}</dd></div><div><dt>Latest ETA / actual delivery</dt><dd>${stamp(s.deliveryActual||s.eta)}</dd></div><div><dt>Last carrier-reported location</dt><dd>${s.lastLocation||'Unavailable'}</dd></div><div><dt>Location / source timestamp</dt><dd>${stamp(s.sourceUpdatedAt)}</dd></div></dl></section><section class="drawer-section"><h3>Shipment information</h3><dl class="fact-grid">${[['Load ID',s.id],['Customer PO',s.po],['BOL',s.bol],['Freight',s.pallets+' pallets · '+num(s.weight)+' lb'],['Dimensions / class',s.dimensions+' · '+s.class],['Handling',s.handling+' · '+(s.stackable?'Stackable':'Not stackable')]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><div class="card table-wrap"><table><thead><tr><th>PRO</th><th>Piece status</th></tr></thead><tbody>${s.pros.map(p=>`<tr><td>${p.number}</td><td>${pill(p.status,p.status==='Delivered'?'teal':'blue')}</td></tr>`).join('')}</tbody></table></div></section>${finance()?`<section class="drawer-section"><h3>Customer charges</h3><dl class="fact-grid">${[['Linehaul',money(s.charges.linehaul)],['Fuel',money(s.charges.fuel)],['Accessorials',money(s.charges.accessorial)+(s.charges.accessorialReason?' · '+s.charges.accessorialReason:'')],['Expected total',money(s.charges.expected)],['Invoiced total',s.charges.invoiced===null?'Not invoiced':money(s.charges.invoiced)]].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl></section>`:''}<section class="drawer-section"><h3>Exceptions (${ex.length})</h3>${ex.map(e=>`<div class="conversation"><div class="between">${link(e.type,'exception',e.id)}${pill(e.status,e.status==='Resolved'?'teal':'amber')}</div><small>${e.owner} · ${esc(e.nextAction)}</small></div>`).join('')||'<p class="small muted">No exceptions recorded.</p>'}</section>`;
if(tab==='Milestones')body=`<div class="note page-note">Normalized milestones preserve each original carrier event and source timestamp. Delay and tracking alerts do not replace carrier status.</div><ol class="timeline">${s.events.map(e=>`<li><strong>${e.name}</strong><small>${stamp(e.time)}</small><small>${e.source} · ${e.raw}</small></li>`).join('')}</ol><div class="note" style="margin-top:20px">Last successful demo sync: ${stamp(SYNC)}<br>Last source update: ${stamp(s.sourceUpdatedAt)}</div>`;
if(tab==='Documents')body=`<div class="note page-note">Available documents open as synthetic samples. No customer documents or live storage are connected.</div>${Object.entries(s.documents).filter(([name])=>name!=='Invoice'||finance()).map(([name,available])=>`<div class="document">${icon('file')}<div><h3>${name==='BOL'?'Bill of lading':name==='POD'?'Proof of delivery':'Customer invoice'}</h3><p>${available?'Synthetic sample · '+s.id:'Unavailable · Not supplied in the source snapshot'}</p></div>${available?btn('View sample','document',s.id+'|'+name,'sm'):pill('Unavailable')}</div>`).join('')}`;
if(tab==='Conversation')body=`<div class="note page-note">Local demo discussion. Entries are stored in this browser and are not sent to anyone.</div>${s.notes.filter(n=>internal()||n.visibility==='Customer').map(n=>`<article class="conversation"><div class="between"><strong>${esc(n.author)}</strong>${pill(n.visibility,n.visibility==='Internal BHD'?'amber':'blue')}</div><small>${stamp(n.time)}</small><p>${esc(n.text)}</p></article>`).join('')||'<p class="small muted" style="margin:20px 0">No visible notes yet.</p>'}${editable()?`<form data-form="shipment-note" data-id="${s.id}"><label class="form-label">Add an update<textarea name="note" required maxlength="2000" placeholder="Add context, a question, or the next action…"></textarea></label><div class="between"><select name="visibility" aria-label="Note visibility"><option>Customer</option>${internal()?'<option>Internal BHD</option>':''}</select><button class="btn primary" type="submit">Add local note</button></div></form>`:'<div class="note">Finance demo role has read-only access to conversations.</div>'}<h3 style="margin-top:24px;font-size:12px">Activity history</h3>${[...s.history,...ex.flatMap(e=>e.history.map(h=>({...h,text:e.id+' · '+h.text})))].filter(h=>internal()||h.visibility!=='Internal BHD').map(h=>`<div class="conversation"><small>${stamp(h.time)}</small><p>${esc(h.text)}</p></div>`).join('')||'<p class="small muted">No local activity yet.</p>'}`;
overlay(`<div class="drawer-head"><div class="between"><div><small>SHIPMENT DETAILS</small><h2 id="dialog-title">${s.id}</h2><p>${s.pros.map(p=>p.number).join(' / ')} · ${s.po}</p></div>${closeBtn()}</div></div><nav class="drawer-tabs" aria-label="Shipment sections">${['Overview','Milestones','Documents','Conversation'].map(t=>`<button class="${t===tab?'active':''}" data-action="drawer-tab" data-id="${t}">${t}</button>`).join('')}</nav><div class="drawer-body">${body}</div>`)}
function openException(id){const e=data.exceptions.find(e=>e.id===id);if(!e||!allPermitted().some(s=>s.id===e.loadId))return;drawer={kind:'exception',id};overlay(`<div class="drawer-head"><div class="between"><div><small>${e.id} · ${e.loadId}</small><h2 id="dialog-title">${e.type}</h2><p>${lookup(e.facility).name} · ${e.source}</p></div>${closeBtn()}</div></div><div class="drawer-body"><div class="between" style="margin-bottom:20px">${severity(e)}${link('Open shipment '+icon('arrow'),'shipment',e.loadId)}</div><dl class="fact-grid"><div><dt>Detected</dt><dd>${stamp(e.detectedAt)}</dd></div><div><dt>Current due time</dt><dd>${stamp(e.dueAt)}</dd></div></dl>${editable()?`<form data-form="exception" data-id="${e.id}"><div class="form-grid"><label>Owner<select name="owner" aria-label="Owner">${options(owners,e.owner)}</select></label><label>Status<select name="status" aria-label="Status">${options(exceptionStates,e.status)}</select></label><label>Severity<select name="severity" aria-label="Severity">${options(['High','Medium','Low'],e.severity)}</select></label><label>Due time (UTC)<input type="datetime-local" name="dueAt" value="${e.dueAt.slice(0,16)}" required></label></div><label class="form-label">Next action<input name="nextAction" value="${esc(e.nextAction)}" required maxlength="300"></label><label class="form-label">Resolution reason <small>Required when resolving</small><input name="reason" value="${esc(e.reason)}" maxlength="500" placeholder="What was verified or corrected?"></label><label class="form-label">Add a note<textarea name="note" maxlength="2000" placeholder="Document the action, carrier response, or outcome…"></textarea></label><div class="between wrap"><select name="visibility" aria-label="Exception note visibility"><option>Customer</option>${internal()?'<option>Internal BHD</option>':''}</select><div class="row">${btn('Escalate','escalate',e.id)}<button class="btn primary" type="submit">Save changes</button></div></div></form>`:'<div class="note">This demo role has read-only exception access.</div>'}<div class="note" style="margin-top:18px">Changes are local to this browser. Resolving this issue leaves the shipment's carrier status unchanged.</div><h3 style="margin:24px 0 12px;font-size:12px">Resolution & audit history</h3>${e.history.filter(h=>internal()||h.visibility==='Customer').map(h=>`<div class="conversation"><div class="between"><small>${stamp(h.time)}</small>${pill(h.visibility)}</div><p>${esc(h.text)}</p></div>`).join('')}</div>`)}
function openOpportunity(id){const o=opportunityDefs.find(o=>o.id===id),list=opportunityShips(o),r=data.reviews.find(r=>r.id===id),sum=list.reduce((a,s)=>a+s.charges.expected,0);modal(o.title,`<div class="between" style="margin-bottom:15px">${pill(o.type,'lime')}<small>${o.id}</small></div><p><strong>${o.route}</strong></p><p>${o.description}</p><div class="note">Proposed action: ${o.action}<br>Review owner: ${r?'BHD Operations':'Unassigned'}</div><h3 style="margin-top:20px">Assumptions & service implications</h3><ul class="checklist">${o.assumptions.map(a=>`<li>${a}</li>`).join('')}</ul><div class="note amber">${o.savings}${id==='OP-101'&&finance()?'<br>Illustrative range for the currently selected loads: '+money(sum*.10)+'–'+money(sum*.15)+'.':''}</div><h3 style="margin:18px 0 10px">Supporting shipments (${list.length})</h3>${list.slice(0,12).map(s=>`<div class="between" style="padding:7px 0">${link(s.id,'shipment',s.id)}<small>${s.pallets} pallets · ${num(s.weight)} lb · ${shortDate(s.pickupCommitment)}</small></div>`).join('')||'<p>No supporting shipments match your current filters.</p>'}${list.length>12?'<p class="small muted">'+(list.length-12)+' additional matching loads.</p>':''}<div class="modal-actions">${r?pill('Awaiting BHD review','teal'):`<button class="btn primary" data-action="submit-review" data-id="${id}" ${!list.length||!editable()?'disabled':''}>Send for BHD review</button>`}</div><p class="small muted" style="margin-top:10px">Creates a local demo review item. Does not contact BHD, book, or modify freight.</p>`)}


function mansfieldResearch(){modal('Why these features fit Mansfield',`<p>These additions are based on Mansfield’s published product priorities. They are proposed ways for BHD to add value, not claims about current Mansfield freight performance.</p>${mansfieldSources.map(s=>`<article class="research-source"><h3><a href="${s.url}" target="_blank" rel="noopener">${s.name}</a></h3><p>${s.finding}</p></article>`).join('')}<div class="note lime">Recommendation: use the control tower as the freight execution layer alongside FuelNet. Start with delivery exceptions, evidence, and invoice review; then connect supply urgency only after site mappings and a supported inventory feed are agreed.</div><p class="small muted" style="margin-top:14px">Sources reviewed October 30, 2026. The public location directory is not a complete operational receiving-site master. All demonstrations use synthetic freight; no affiliation or verified customer relationship is asserted.</p>`)}
function siteReview(id){const f=facilities.find(x=>x.id===id),r=(data.siteReviews||[]).find(x=>x.facilityId===id)||{};modal('Receiving-site review · '+f.name,`<div class="note page-note"><strong>Published:</strong> ${esc(f.address)}<br>${esc(f.sourceNote)}</div><p>This is a local planning annotation. It does not independently verify the location or update Sunnybrook.</p><form data-form="site-review" data-id="${id}"><div class="form-grid"><label>Review owner<input name="owner" required value="${esc(r.owner||'BHD Operations')}"></label><label>Proposed site use<select name="use">${options(['Unconfirmed','Office only','Freight receiving — needs validation','Mailing only'],r.use||'Unconfirmed')}</select></label></div><label class="form-label">Physical receiving address to validate<input name="receivingAddress" value="${esc(r.receivingAddress||'')}" placeholder="Do not use a PO box or office without confirmation"></label><div class="form-grid"><label>Receiving hours<input name="hours" value="${esc(r.hours||'')}" placeholder="Unconfirmed"></label><label>Operational contact<input name="contact" value="${esc(r.contact||'')}" placeholder="Confirm with Mansfield"></label></div><label class="form-label">Appointment, access, equipment, product, or validation notes<textarea name="notes" maxlength="2000">${esc(r.notes||'')}</textarea></label><div class="modal-actions"><button class="btn primary" type="submit" ${!editable()?'disabled':''}>Save local review</button></div></form>`)}

function locationSources(){modal('Mansfield location sources',`<p><strong>11 detailed location entries</strong> from <a href="https://mansfield.energy/locations/" target="_blank" rel="noopener">Mansfield Energy’s official directory</a>, reviewed October 30, 2026. They include offices, headquarters, Power & Gas, Service Partners, and mailing entries. This is not a verified master list of warehouses or receiving facilities.</p><div class="note amber page-note">The directory summary names Roseville and Troy, while its detailed entries name Loretto and Sidney. Several linked maps also disagree with the text. We retained the detailed listings, identified the discrepancies, and did not create duplicate sites from the summary.</div><div class="source-location-list">${facilities.map(f=>`<article><h3>${esc(f.name)}, ${f.state}</h3><p>${esc(f.address)}</p><small>${esc(f.quality)} · ${esc(f.sourceNote)}</small></article>`).join('')}</div><div class="note" style="margin-top:16px">All shipments, charges, carrier events, contacts in demo conversations, and lane flows are synthetic. No Mansfield shipment data or customer relationship is asserted. Mark and Calgary are city/mail-contact pins; Sidney is approximate pending address validation. Geographic outlines use Census-derived us-atlas and Natural Earth world-atlas data.</div>`)}
let mapDrag=null;
document.addEventListener('pointerdown',e=>{if(e.button!==0||!e.target.closest('.geo-map')||e.target.closest('[data-action],button,select'))return;const box=e.target.closest('.geo-map').getBoundingClientRect();mapDrag={x:e.clientX,y:e.clientY,width:box.width};document.documentElement.setPointerCapture(e.pointerId)});
document.addEventListener('pointermove',e=>{if(!mapDrag)return;const dx=(e.clientX-mapDrag.x)/mapDrag.width*900,dy=(e.clientY-mapDrag.y)/mapDrag.width*900;mapDrag.x=e.clientX;mapDrag.y=e.clientY;panMap(dx,dy);render()});
document.addEventListener('pointerup',e=>{if(mapDrag){mapDrag=null;if(document.documentElement.hasPointerCapture(e.pointerId))document.documentElement.releasePointerCapture(e.pointerId)}});
document.addEventListener('pointercancel',()=>mapDrag=null);

function definitions(){modal('Data & metric definitions',`<p>One deterministic dataset: 176 unique synthetic loads, 11 published customer locations, five carriers. Demo as of <strong>Oct 30, 2026, noon EDT</strong>.</p><dl class="definitions"><dt>Reporting period and date basis</dt><dd>Loads are selected by original committed pickup date, evaluated in America/Indiana/Indianapolis. The default period is October 1–30. Scheduled November deliveries remain in the October pickup cohort. Facility schedules use the facility's local time. Date filters apply to every section.</dd><dt>Active shipments</dt><dd>Unique loads whose carrier status is neither Delivered nor Cancelled. Partial deliveries and Unknown status remain active; each load is counted once regardless of PRO count.</dd><dt>Pickups and deliveries due today</dt><dd>Noncancelled loads with an original commitment dated October 30. Includes completed events that were due today. The main KPIs use Indianapolis time; the facility schedule uses each facility's zone.</dd><dt>Open exceptions</dt><dd>Exception records attached to the selected loads, excluding Resolved. Multiple different issues can affect one load; therefore this may exceed the number of affected loads.</dd><dt>On-time delivery</dt><dd>Numerator: fully delivered loads with actual delivery at or before the original commitment. Denominator: fully delivered loads with an actual delivery and original commitment. Cancelled, partial, active, and missing timestamps are excluded. Revised ETAs never change this measure.</dd><dt>On-time pickup</dt><dd>Numerator: noncancelled loads with actual pickup at or before the original commitment. Denominator: noncancelled loads with an observed pickup time. Scheduled and missing actual times are excluded.</dd><dt>Freight spend</dt><dd>Customer invoiced total when available; otherwise expected customer total. Linehaul, fuel, and accessorials are each included once. Cancelled loads excluded. This blends actual invoice charges and estimates, which are shown separately. No carrier buy rates or BHD margin are present.</dd><dt>Facility spend attribution</dt><dd>Overview facility cards show all loads touching that facility, so an interfacility load appears in both endpoint workspaces. Do not sum those cards. The Insights facility chart allocates each load once to its customer origin, or to the customer destination for external inbound freight.</dd><dt>Cost per shipment / hundredweight</dt><dd>Spend divided by noncancelled load count; or spend divided by total known positive pounds / 100. This dataset has complete positive weights. A future adapter must exclude missing or invalid weights and disclose coverage. Match lane, service, class, and weight before drawing efficiency conclusions.</dd><dt>Freshness</dt><dd>Demo sync: ${stamp(SYNC)}. An active load is stale after 24 hours without a carrier source update as of the fixed demo time. Historical delivered events retain their actual age without being misclassified as active tracking failures. Unknown stays Unknown.</dd><dt>Claims and resolution</dt><dd>Claims incidence counts unique loads with a shortage/damage report divided by noncancelled selected loads, not confirmed paid claims. Mean resolution hours uses detected time through the latest resolving action, only for currently resolved exceptions; no sample shows no result.</dd><dt>Local persistence and roles</dt><dd>Changes save only in this browser. Role switching illustrates UI views; it is not production authentication or tenant security. All data shipped to this demo is synthetic. Reset demo removes local changes and saved views.</dd></dl>`)}
function integration(){modal('Integration readiness',`<div class="note lime page-note"><strong>Working now:</strong> browser-local demonstration with replaceable data functions. No live Sunnybrook or USPS connection is claimed.</div><p>The Food It Forward reference CSS, navigation, cards, tables, and drawer design were inspected and adapted. USPS code was not accessible in the connected repository search; no USPS operational components were verified or modified.</p><h3>Required before live operations</h3><ol><li>USPS repository access and its deployment, auth, document, and exception contracts.</li><li>Supported Sunnybrook endpoints, credentials, customer/facility mapping, field dictionary, pagination, incremental cursor, event ordering, and API limits.</li><li>Server-side authentication and tenant/facility authorization across records, search, exports, documents, comments, and aggregates.</li><li>Allowlisted customer financial responses, shared collaboration database, versioned audit trail, and secure document delivery.</li><li>Retry, deduplication, cancellation/correction handling, stale-source policies, time-zone validation, and production acceptance tests.</li></ol><p>Sunnybrook remains responsible for load creation and maintenance. No booking, dispatch, carrier payment, or writeback is included.</p><div class="modal-actions">${btn('Close','close','','primary')}</div>`)}
function guide(){modal('Take the network for a spin',`<p><strong>BHD LTL Control Center</strong><br>Your facilities. Your freight. One network.</p><ol><li>Select a facility on the map. Click <strong>Active shipments</strong> to reconcile its freight.</li><li>Open a network lane, then drill into any supporting shipment.</li><li>Search <strong>OD-781250-B</strong> for a split delivery, or <strong>PO-450233</strong> for stale tracking.</li><li>Open Exceptions, assign an owner, add a note, and resolve an issue with a reason. The carrier status stays unchanged.</li><li>Compare carrier service in Insights. Each percentage includes its denominator.</li><li>Review the Gainesville → Mark consolidation candidate, inspect its assumptions, and send it to the local review queue.</li><li>Export the filtered shipment list. Use the avatar menu to preview roles.</li></ol><div class="note">Synthetic demonstration · 176 shipments · October 2026<br>Comments, assignments, saved views, and review items stay in this browser. Demo role switching is illustrative; live integration and server authorization remain to be implemented.</div><div class="modal-actions">${btn('Start exploring','close','','primary')}</div>`)}
function userMenu(){modal('Demo user & access',`<div class="row" style="margin-bottom:20px"><span class="avatar">AM</span><div><strong>Alex Morgan</strong><p class="small muted">Demo user · Mansfield Energy example network</p></div></div><label class="form-label">Preview a role<select id="role-select">${options([['corporate','Corporate customer'],['facility','Facility user · Gainesville'],['finance','Customer finance · read only'],['operations','BHD operations'],['admin','Administrator']],role)}</select></label><div class="note amber">This switch illustrates interfaces only. It is not production authentication. This static demonstration contains no real customer or confidential financial data.</div><div class="modal-actions">${btn('Apply demo role','apply-role','','primary')}</div>`)}
function download(text,name,type='text/csv;charset=utf-8'){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([text],{type}));a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000)}
const clearFilters=()=>{filters=emptyFilters();if(role==='facility')filters.facility='GNV';page=1;facilityPage=null};
function nav(n){view=n;facilityPage=null;page=1;render();window.scrollTo({top:0,behavior:'instant'})}
function action(a,id,node){switch(a){
case'nav':nav(id);break;
case'close':closeOverlay();break;
case'overlay-background':if(node===eventTarget)closeOverlay();break;
case'alerts':view='Exceptions';filters.metric='';render();break;
case'user':userMenu();break;
case'continuity-sample':sampleScenario();render();break;
case'mansfield-research':mansfieldResearch();break;
case'site-review':siteReview(id);break;
case'guide':guide();break;
case'definitions':definitions();break;
case'integration':integration();break;
case'apply-role':role=$('#role-select').value;clearFilters();closeOverlay();render();toast('Demo role applied. This is not production authentication.');break;
case'reset-filters':clearFilters();render();break;
case'clear-filter':filters[id]=emptyFilters()[id];page=1;render();break;
case'metric':if(id==='spend'&&!finance()){toast('Finance access is unavailable in this demo role.');break}filters.metric=id==='exceptions'?'':id;view=id==='exceptions'?'Exceptions':'Shipments';facilityPage=null;exceptionTab='Open';page=1;render();break;
case'map-mode':mapMode=id;render();break;
case'map-zoom-in':zoomMap(1.25);render();break;
case'map-zoom-out':zoomMap(.8);render();break;
case'map-fit':setMapExtent(id);render();break;
case'location-sources':locationSources();break;
case'map-list':mapList=!mapList;render();break;
case'map-facility':if(role==='facility'&&id!=='GNV'){toast('This demo role is limited to Gainesville.');break}filters.facility=filters.facility===id&&role!=='facility'?'all':id;filters.lane='';filters.metric='';page=1;render();break;
case'lane':filters.lane=id;filters.metric=mapMode==='active'&&view==='Overview'?'active':'';view='Shipments';facilityPage=null;page=1;closeOverlay();render();break;
case'carrier':filters.carrier=id;view='Shipments';page=1;render();break;
case'facility':if(role==='facility'&&id!=='GNV')break;facilityPage=id;view='Facilities';filters.facility=id;filters.metric='';filters.lane='';render();window.scrollTo({top:0,behavior:'instant'});break;
case'facility-back':facilityPage=null;filters.facility=role==='facility'?'GNV':'all';filters.direction='all';render();break;
case'facility-direction':filters.direction=id;view='Shipments';facilityPage=null;render();break;
case'sort':if(sortKey===id)sortAsc=!sortAsc;else{sortKey=id;sortAsc=true}render();break;
case'prev':page--;render();break;
case'next':page++;render();break;
case'saved-preset':filters.metric=id;page=1;render();break;
case'save-view':modal('Save this shipment view',`<form data-form="save-view"><label class="form-label">View name<input name="name" required maxlength="60" placeholder="e.g. Gainesville active freight"></label><p>The current facility, date, movement, carrier, status, search, and lane filters will be saved in this browser.</p><div class="modal-actions"><button type="submit" class="btn primary">Save view</button></div></form>`);break;
case'columns':modal('Shipment columns',`<form data-form="columns"><p>Load, route, carrier, status, commitments, and source update are always shown.</p><div class="columns-check">${[['references','PO & BOL references'],['weight','Pallets, weight & class'],...(finance()?[['charges','Customer charges']]:[])].map(([k,l])=>`<label><input name="${k}" type="checkbox" ${columns[k]?'checked':''}>${l}</label>`).join('')}</div><div class="modal-actions"><button class="btn primary" type="submit">Apply columns</button></div></form>`);break;
case'export':download(csv(ships(),finance()),'BHD_LTL_filtered_shipments.csv');toast('Exported '+ships().length+' unique synthetic loads with current filters.');break;
case'shipment':openShipment(id,'Overview');break;
case'drawer-tab':openShipment(drawer.id,id);break;
case'exception-tab':exceptionTab=id;render();break;
case'exception':openException(id);break;
case'escalate':if(!editable())break;updateException(data,id,{severity:'High',owner:'BHD Operations',status:'Assigned'},'Escalated to BHD Operations in the local demo. No notification sent.','Customer');save();render();openException(id);toast('Escalation recorded locally.');break;
case'opportunity':openOpportunity(id);break;
case'submit-review':if(!editable())break;{const o=opportunityDefs.find(o=>o.id===id),list=opportunityShips(o);if(!list.length)break;if(!data.reviews.some(r=>r.id===id))data.reviews.push({id,title:o.title,createdAt:new Date().toISOString(),loadIds:list.map(s=>s.id),owner:'BHD Operations'});save();render();openOpportunity(id);toast('Review item saved locally. No freight was changed.')}break;
case'document':{const[loadId,kind]=id.split('|'),s=allPermitted().find(s=>s.id===loadId);if(!s?.documents[kind]||(kind==='Invoice'&&!finance())){toast('Document unavailable for this demo role.');break}modal(kind+' · Synthetic sample',`<div class="note amber page-note">DEMONSTRATION DOCUMENT — NOT VALID FOR SHIPPING OR BILLING</div><dl class="fact-grid">${[['Load',s.id],['Document',kind],['Origin',lookup(s.origin).name],['Destination',lookup(s.destination).name],['PO',s.po],['Freight',s.pallets+' pallets / '+num(s.weight)+' lb']].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl><p>${kind==='Invoice'?money(s.charges.invoiced)+' synthetic customer invoice.':kind==='POD'?'Synthetic receipt confirmation. No real signature is represented.':'Synthetic bill of lading. No actual shipment authorization.'}</p><div class="modal-actions">${btn('Return to documents','return-documents',s.id,'primary')}</div>`)}break;
case'return-documents':openShipment(id,'Documents');break;
case'reset-demo':modal('Reset the demonstration?',`<p>This removes notes, assignments, resolutions, review items, and saved views created in this browser, then restores the original synthetic dataset.</p><div class="modal-actions">${btn('Keep changes','close')}${btn('Reset demo','confirm-reset','','primary')}</div>`);break;
case'confirm-reset':data=makeData();save();clearFilters();view='Overview';role='corporate';filters=emptyFilters();mapList=window.matchMedia('(max-width:600px)').matches;mapMode='locations';resetMapCamera();resetScenario();mapWeight='volume';exceptionTab='Open';columns={references:false,weight:false,charges:true};closeOverlay();render();toast('Original synthetic demonstration restored.');break;
}}
let eventTarget=null;document.addEventListener('click',e=>{const n=e.target.closest('[data-action]');if(!n)return;eventTarget=e.target;if(n.dataset.action==='overlay-background'&&n!==e.target)return;action(n.dataset.action,n.dataset.id,n)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#overlay').innerHTML){closeOverlay();return}if(e.key==='Tab'&&$('#overlay').innerHTML){const list=[...$('#overlay').querySelectorAll('button:not([disabled]),input,select,textarea,a[href],[tabindex="0"]')];if(!list.length)return;const first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}if(['Enter',' '].includes(e.key)&&e.target.matches('g[role="button"]')){e.preventDefault();action(e.target.dataset.action,e.target.dataset.id,e.target)}});
document.addEventListener('input',e=>{if(e.target.id==='global-search'){filters.q=e.target.value;page=1;render()}});
document.addEventListener('change',e=>{const n=e.target;if(n.dataset.filter){filters[n.dataset.filter]=n.value;filters.metric='';page=1;if(n.dataset.filter==='facility'){filters.lane='';if(facilityPage)facilityPage=n.value==='all'?null:n.value}render()}else if(n.id==='map-weight'){mapWeight=n.value;render()}else if(n.id==='insight-dimension'){insightDimension=n.value;render()}else if(n.id==='saved-view'&&n.value!==''){filters={...emptyFilters(),...data.savedViews[+n.value].filters};if(role==='facility')filters.facility='GNV';page=1;render()}});
document.addEventListener('submit',e=>{const form=e.target;if(!form.dataset.form)return;e.preventDefault();const f=new FormData(form),id=form.dataset.id;switch(form.dataset.form){case'continuity':{applyScenario(Object.fromEntries(['inventory','dailyUse','reserve','etaHours','delivery','capacity'].map(k=>[k,Number(f.get(k))])));render();break}case'site-review':{if(!editable())return;const r={facilityId:id,owner:String(f.get('owner')),use:String(f.get('use')),receivingAddress:String(f.get('receivingAddress')),hours:String(f.get('hours')),contact:String(f.get('contact')),notes:String(f.get('notes')),updatedAt:new Date().toISOString()};data.siteReviews??=[];data.siteReviews=data.siteReviews.filter(x=>x.facilityId!==id);data.siteReviews.push(r);save();closeOverlay();render();toast('Local review saved. Public-source verification status is unchanged.');break}case'columns':for(const k of Object.keys(columns))columns[k]=f.has(k);closeOverlay();render();break;case'save-view':{const name=String(f.get('name')).trim();if(!name)return;data.savedViews.push({name,filters:{...filters}});save();closeOverlay();render();toast('View saved in this browser.');break}case'shipment-note':{if(!editable())return;const s=allPermitted().find(s=>s.id===id),text=String(f.get('note')).trim();if(!s||!text)return;const visibility=internal()?String(f.get('visibility')):'Customer',time=new Date().toISOString();s.notes.push({text,visibility,time,author:internal()?'BHD Operations':'Alex Morgan'});s.history.push({text:'Added a '+visibility.toLowerCase()+' note.',time,visibility});save();openShipment(id,'Conversation');toast('Note saved locally.');break}case'exception':{if(!editable())return;const patch=Object.fromEntries(['owner','status','severity','nextAction','reason'].map(k=>[k,String(f.get(k)||'').trim()]));if(patch.status==='Resolved'&&!patch.reason){form.elements.reason.setCustomValidity('Enter a resolution reason before resolving.');form.elements.reason.reportValidity();form.elements.reason.addEventListener('input',()=>form.elements.reason.setCustomValidity(''),{once:true});return}patch.dueAt=new Date(String(f.get('dueAt'))+'Z').toISOString();updateException(data,id,patch,String(f.get('note')).trim(),internal()?String(f.get('visibility')):'Customer');save();render();openException(id);toast('Exception saved. Carrier shipment status is unchanged.');break}}});
window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#load='))openShipment(decodeURIComponent(location.hash.slice(6)),'Overview')});
try{render();if(location.hash.startsWith('#load='))openShipment(decodeURIComponent(location.hash.slice(6)),'Overview')}catch(e){$('#app').innerHTML='<div class="empty"><h1>We could not load the demonstration.</h1><p>Your local browser state may be incompatible. Reload the page or reset the local demo.</p><button class="btn primary" id="recover">Reset local demo</button></div>';$('#recover').onclick=()=>{localStorage.removeItem(STORAGE);location.reload()};console.error(e)}
